package android.app;
public class Fragment implements android.content.ComponentCallbacks { private Activity activity; private android.os.Bundle arguments; private boolean added; public Fragment() {} public Activity getActivity() { return activity; } public android.content.Context getContext() { return activity; } public FragmentManager getFragmentManager() { return activity==null?null:new FragmentManager(); } public void setArguments(android.os.Bundle b) { arguments=b; } public android.os.Bundle getArguments() { return arguments; } public boolean isAdded() { return added; } public void onAttach(Activity a) { activity=a; added=true; } public void onCreate(android.os.Bundle b) {} public void onStart() {} public void onResume() {} public void onPause() {} public void onStop() {} public void onDestroy() {} public void onDetach() { added=false; activity=null; } public void onConfigurationChanged(android.content.res.Configuration c) {} public void onLowMemory() {}  public void onActivityCreated(android.os.Bundle state) {}
}
